PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS statcast_backfill_dates (statcast_backfill_date_id INTEGER PRIMARY KEY AUTOINCREMENT,calendar_date TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','COMPLETE','EMPTY','FAILED')),source_rows INTEGER NOT NULL DEFAULT 0,valid_rows INTEGER NOT NULL DEFAULT 0,stored_pitch_events INTEGER NOT NULL DEFAULT 0,pitcher_games INTEGER NOT NULL DEFAULT 0,last_error TEXT,attempted_at TEXT,completed_at TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_statcast_backfill_dates_status_date ON statcast_backfill_dates(status,calendar_date);
CREATE TABLE IF NOT EXISTS statcast_backfill_certifications (statcast_backfill_certification_id INTEGER PRIMARY KEY AUTOINCREMENT,backtest_run_id INTEGER NOT NULL,backtest_dataset_build_id INTEGER NOT NULL,feature_date TEXT NOT NULL,pitcher_mlb_id INTEGER NOT NULL,certification_status TEXT NOT NULL CHECK(certification_status IN ('RESEARCH_CERTIFIED','EXCLUDED')),source_window_complete INTEGER NOT NULL DEFAULT 0 CHECK(source_window_complete IN (0,1)),games_lookback INTEGER NOT NULL DEFAULT 0,pitches_lookback INTEGER NOT NULL DEFAULT 0,feature_quality_score INTEGER NOT NULL DEFAULT 0,max_source_game_date TEXT,reasons_json TEXT NOT NULL DEFAULT '[]',evidence_json TEXT NOT NULL DEFAULT '{}',certified_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(backtest_run_id) REFERENCES backtest_runs(backtest_run_id),FOREIGN KEY(backtest_dataset_build_id) REFERENCES backtest_dataset_builds(backtest_dataset_build_id),UNIQUE(backtest_run_id,feature_date,pitcher_mlb_id));
CREATE INDEX IF NOT EXISTS idx_statcast_cert_run_date ON statcast_backfill_certifications(backtest_run_id,feature_date,certification_status);
